\(I_{\textit{Eng.}}(\textit{Jo}) = \ct{j}\)  \(I_{\textit{Eng.}}(\textit{Bo}) = \ct{b}\)  \(I_{\textit{Eng.}}(\textit{runs}) = \{\ct{j}, \ct{b}\}\)  \(I_{\textit{Eng.}}(\textit{jumps}) = \{\ct{j}\}\)  \(I_{\textit{Eng.}}(\textit{and}) = g \text{   (where }g(s_{1}, s_{2}) = s_{1} ∩ s_{2}\text{)}\)

